package app.thawani

internal fun cards6(): List<Card> = listOf(
Card("p31","vehicle_road","اشتعال أو حريق المركبة","998","حرج جداً — إخلاء فوري وعدم فتح الكبوت","c","لا تفتح غطاء المحرك (الكبوت) بالكامل إذا رأيت دخاناً أو لهباً يخرج منه؛ لأن فتحه يدخل الأكسجين دفعة واحدة ويفجر اللهب في وجهك.",listOf("قف فوراً في أقصى الكتف الأيمن، أطفئ المحرك تماماً (لإيقاف ضخ الوقود)، وشغّل الفلشر.","أخرج جميع الركاب فوراً وابتعدوا عن المركبة بمسافة لا تقل عن 30 إلى 50 متراً عكس اتجاه الريح.","اتصل بالدفاع المدني (998) أو (911).","إذا كان الحريق في بدايته البسيطة جداً وتوفرت طفاية حريق: وجّه فوهة الطفاية من خلال الشبك الأمامي أو من فتحة صغيرة جداً للكبوت دون رفعه.","في السيارات الهجينة أو الكهربائية (PHEV/EV): إذا صدر الدخان أو الصوت من أسفل المركبة (البطارية عالية الجهد)، ابتعد فوراً ولا تحاول إطفاءها يدوياً وأبلغ الدفاع المدني بأنها مركبة هجينة/كهربائية."),listOf("لا ترفع غطاء المحرك باليد عند وجود حريق.","لا تعد للسيارة المشتعلة لأخذ الجوال أو الأوراق الشخصية."),listOf("تثبيت طفاية حريق بودرة جافة (1-2 كجم) تحت مقعد السائق أو الراكب الأمامي."),listOf("المركبة والطريق","السفر"),listOf(Link("الدفاع المدني السعودي: السلامة والإنذار","https://998.gov.sa/")),listOf()),
Card("p32","weather_outdoor","ضربة الشمس والإجهاد الحراري الشديد","997","حرج — خفض حرارة الجسم فوراً","w","ضربة الشمس طارئ طبي حرج (حرارة الجسم فوق 40 مع جفاف الجلد أو تشوش الوعي)؛ التبريد الخارجي الفوري بالماء البارد والتهوية يسبق أي إجراء آخر.",listOf("انقل المصاب فوراً إلى مكان مظلل ومكيف أو جيد التهوية، واطلب الاتصال بـ 997.","خفف ملابسه الخارجية، وارفَع ساقيه قليلاً أثناء الاستلقاء.","برّد جسم المصاب بسرعة: رشّ جسمه بالماء الفاتر/البارد مع توجيه مروحة نحوه، وضع كمادات باردة تحت الإبطين، وحول الرقبة، وأعلى الفخذين.","إذا كان المصاب واعياً تماماً (في حالة الإجهاد الحراري وليس فاقداً للوعي): أعطه رشفات متدرجة من الماء البارد أو محلول الجفاف (ORS).","راقب مستوى الوعي والتنفس باستمرار حتى وصول فرقة الإسعاف."),listOf("لا تعطِ السوائل عن طريق الفم لمصاب يعاني من تشوش ذهني أو دوخة شديدة أو غياب عن الوعي.","لا تعتمد على خافضات الحرارة الدوائية (مثل الباراسيتامول) لعلاج ضربة الشمس لأنها غير فعالة في هذه الحالة."),listOf("علامات ضربة الشمس الحرجة: توقف التعرق، احمرار وسخونة الجلد، هذيان أو تلعثم، تسارع شديد بالنبض."),listOf("الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: ضربة الشمس","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/022.aspx")),listOf()),
Card("p33","weather_outdoor","لدغات العقارب والثعابين في البر","937","طوارئ سموم برية — تثبيت الطرف وعدم جرح المكان","d","لا تقم أبداً بجرح مكان اللدغة بالسكين أو مص السم بالفم أو ربط الطرف بحبل مشدود يقطع الدم؛ فهذه الأخطاء تزيد تلف الأنسجة وتسرع المضاعفات.",listOf("أبعد المصاب عن مكان العقرب أو الثعبان، وأجلسه في وضع راحة تامة وهدّئ من روعه (لأن التوتر والحركة يسرعان ضخ الدم وانتشار السم).","ثبّت الطرف الملدوغ بجبيرة واجعله في مستوى القلب أو أخفض قليلاً بدون تحريكه.","انزع الخواتم والساعات والأحذية الضيقة من الطرف المصاب قبل أن يبدأ بالتورم.","نظف مكان اللدغة بالماء والصابون بلطف، وفي لدغة العقرب يمكنك وضع كمادة باردة لتخفيف الألم الموضعي.","اتصل فوراً بـ 997 أو خط السموم (937) وتوجه لأقرب مستشفى لتلقي المصل المضاد."),listOf("لا تقطع أو تشق الجلد بموس أو سكين ولا تمص السم بفمك أبداً.","لا تربط تورنيكيه (عاصبة قاطعة للدم) في لدغات الثعابين والعقارب لأن حصر السم يسبب غرغرينا وبتر للطرف."),listOf("نفض الأحذية والفرش قبل ارتدائها أو النوم عليها في المخيمات."),listOf("التخييم","الاستراحة","السفر"),listOf(Link("وزارة الصحة: اللدغات واللسعات","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/015.aspx")),listOf(Link("إسعاف المصاب باللدغات السامة · الهلال الأحمر السعودي","https://youtu.be/4iym0m9o4pY"))),
Card("p34","weather_outdoor","السيول والأمطار الغزيرة واحتجاز المركبة بالماء","998","تحذير دفاع مدني — لا تجازف بعبور الأودية","t","لا تعبر أي وادٍ أو تجمع مياه جارية بسيارتك مهما بدت المياه ضحلة؛ فارتفاع 30 سم من المياه الجارية كفيل بجرف سيارة صغيرة، و60 سم يجرف سيارات الدفع الرباعي.",listOf("ابتعد فوراً عن بطون الأودية، مجاري السيول، والمناطق المنخفضة وأعمدة الإنارة الكهربائية.","إذا حاصرت المياه سيارتك وتوقفت: فكّ حزام الأمان فوراً لك ولجميع الركاب (بدءاً بالأطفال الأكبر فالأصغر).","افتح نوافذ السيارة الكهربائية فوراً قبل أن يصل الماء لمستوى الدوائر الكهربائية ويعطلها.","إذا تعذر فتح الباب بسبب ضغط الماء ولا تفتح النافذة: اكسر إحدى النوافذ الجانبية (وليس الزجاج الأمامي) من زاويتها السفلية باستخدام كاسر الزجاج أو قضيب مسند الرأس المعدني.","اخرج من النافذة واصعد لسطح المركبة واتصل بالدفاع المدني (998) أو (911)."),listOf("لا تحاول عبور السيول بالمركبة أو المشي في مياه جارية.","لا تحاول كسر الزجاج الأمامي للمركبة لأنه مزدوج ومصفح؛ اكسر الزجاج الجانبي فقط."),listOf("الاحتفاظ بأداة كسر الزجاج وقطع حزام الأمان معلقة في الكونسول الوسطي."),listOf("الاستراحة","التخييم","السفر"),listOf(Link("الدفاع المدني السعودي: السلامة والإنذار","https://998.gov.sa/")),listOf()),
Card("p35","weather_outdoor","موجات الغبار ونوبات الربو الحادة","937","وقاية وإسعاف تنفسي — حماية مرضى الربو","w","في نوبة الربو الحادة: أجلس المريض في وضع مستقيم مائل قليلاً للأمام (لا تجعله يستلقي على ظهره أبداً) وأعطه البخاخ الإسعافي فوراً.",listOf("عند بدء نوبة ضيق التنفس أو الربو: أجلس المصاب بهدوء وفكّ أي ملابس ضيقة حول الرقبة والصدر.","استخدم البخاخ الموسع للشعب الهوائية (الإسعافي مثل السالبوتامول) بمعدل 4 بخات (بخة واحدة ثم 4 أنفاس عميقة، وتكرر 4 مرات).","انتظر 4 دقائق؛ إذا لم يتحسن التنفس، كرر إعطاء 4 بخات أخرى.","إذا استمر ضيق التنفس أو ازرقّت الشفاه أو عجز المريض عن إكمال جملة واحدة: اتصل فوراً بـ 997 مع الاستمرار بإعطاء 4 بخات كل 4 دقائق حتى وصول الإسعاف.","أثناء الغبار: أغلق النوافذ بإحكام، وشغّل التكييف على وضع تدوير الهواء الداخلي مع منقي الهواء."),listOf("لا تجعل مصاب نوبة الربو يستلقي على ظهره لأن ذلك يزيد صعوبة التنفس."),listOf("تفعيل تدوير الهواء الداخلي (Recirculation) في تكييف السيارة عند الدخول في موجة غبار."),listOf("الاستراحة","التخييم","السفر"),listOf(Link("الهلال الأحمر السعودي: التوعية الإسعافية","https://www.srca.gov.sa/first-aid-awareness/")),listOf(Link("إسعاف مرضى الأزمات التنفسية · الهلال الأحمر السعودي","https://youtu.be/LFi0M8YlX8Q"))),
Card("p36","weather_outdoor","التغريز والانقطاع في الصحراء والبر","911","بقاء وإنقاذ بري — ابقَ بجوار المركبة","w","القاعدة الأولى للنجاة في الصحراء: لا تغادر مركبتك أبداً للسير على الأقدام بحثاً عن الإرسال؛ فالمركبة يسهل رصدها من الطائرات وتوفر الظل والحماية.",listOf("ابقَ بجانب المركبة، واستظل بداخلها أو تحتها نهاراً لتقليل فقدان السوائل بالتعرق.","لتخليص السيارة المغرزة: خفف ضغط الإطارات إلى (12-15 PSI)، وأزل الرمل من أمام الإطارات ومن تحت بطن المركبة، وتحرك للأمام والخلف بهدوء دون حفر.","إذا تعذر الخروج: اتصل بطوارئ (911) وأرسل إحداثيات موقعك.","رشّد استهلاك المياه (اشرب رشفات صغيرة منتظمة ولا تأكل الطعام الجاف إذا كان الماء قليلاً).","ارفع غطاء المحرك وضع قطعة قماش زاهية أو استخدم مرآة المركبة لعكس ضوء الشمس نهاراً والكشاف عند سماع طائرة البحث."),listOf("لا تمشِ في الصحراء نهاراً تحت الشمس الحارقة تحت أي ظرف.","لا تستهلك بطارية الجوال في التصفح؛ فعّل وضع توفير الطاقة الأقصى."),listOf("إبلاغ أحد الأقارب بوجهتك الدقيقة وموعد عودتك المتوقع قبل أي رحلة برية، وحمل جالون ماء إضافي (20 لتر على الأقل)."),listOf("الاستراحة","التخييم","السفر"),listOf(),listOf())
)
